css:
.cc-header { text-align: center; margin-bottom: 15px; }
.cc-party, .cc-table { width: 100%; border-collapse: collapse; margin: 10px 0; }
.cc-party td { vertical-align: top; padding: 6px; }
.cc-table td { border: 1px solid #ccc; padding: 6px 8px; }
.cc-table .grand { font-weight: bold; border-top: 2px solid #333; }
.sign { margin-top: 40px; width: 100%; }
.sign td { border-top: 1px solid #333; padding-top: 5px; font-size: 0.85em; }
.ar { direction: rtl; }
